function validate([s]) {
  if (typeof s !== 'string' || s.length < 2 || s.length > 1000) return 's needs 2 to 1000 letters.';
  if (s.length % 2 !== 0) return 's must have an even length.';
  if (!/^[a-zA-Z]+$/.test(s)) return 's may contain only English letters.';
  return null;
}

