function halvesAreAlike(s) {
  const vowels = new Set('aeiouAEIOU');
  const half = s.length / 2;
  let firstCount = 0;
  let secondCount = 0;
  for (let i = 0; i < half; i++) {
    if (vowels.has(s[i])) {
      firstCount++;
    }
    if (vowels.has(s[i + half])) {
      secondCount++;
    }
  }
  return firstCount === secondCount;
}

brute:
function halvesAreAlike(s) {
  const count = part => (part.match(/[aeiou]/gi) || []).length;
  return count(s.slice(0, s.length / 2)) === count(s.slice(s.length / 2));
}

