function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const vowelBias = rand();
  const letter = () => {
    const ch = rand() < vowelBias ? 'aeiou'[Math.floor(rand() * 5)] : letters[Math.floor(rand() * 26)];
    return rand() < 0.5 ? ch.toUpperCase() : ch;
  };
  const half = size === 'large' ? 400 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 6);
  const front = Array.from({ length: half }, letter);
  let back;
  if (rand() < 0.5) {
    // Shuffle the front half and flip some cases so both halves have the same vowel count.
    back = front.map(ch => (rand() < 0.5 ? ch.toUpperCase() : ch.toLowerCase()));
    for (let i = back.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [back[i], back[j]] = [back[j], back[i]];
    }
  } else {
    back = Array.from({ length: half }, letter);
  }
  return [front.join('') + back.join('')];
}
